class Attn10(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(96, 288)
        self.proj = nn.Linear(96, 96)
        self.norm = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b10 s10 96"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b10, s10, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b10, s10, 96]; k=[b10, s10, 96]; v=[b10, s10, 96]
        q = q.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: q=[b10, s10, 4, 24]
        k = k.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: k=[b10, s10, 4, 24]
        v = v.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: v=[b10, s10, 4, 24]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b10, 4, s10, 24]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b10, 4, 24, s10]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b10, 4, s10, 24]
        scores = q @ k  # expected-shape: scores=[b10, 4, s10, s10]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b10, 4, s10, s10]
        ctx = attn @ v  # expected-shape: ctx=[b10, 4, s10, 24]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b10, s10, 4, 24]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b10, s10, 96]
        out = self.proj(ctx)  # expected-shape: out=[b10, s10, 96]
        out = self.norm(out + x)  # expected-shape: out=[b10, s10, 96]
        return out


