def long_chain_16(x: Float[Array, "b16 16 d16"]):
    v0 = x.mean(axis=0)  # expected-shape: v0=[16, d16]
    v1 = v0 * 0.5
    v2 = jnp.expand_dims(v1, axis=1)
    v3 = jnp.expand_dims(v2, axis=1)
    v4 = jnp.concatenate([v3, v3], axis=1)
    v5 = jnp.swapaxes(v4, 2, 3)  # expected-shape: v5=[16, 2, d16, 1]
    v6 = jnp.concatenate([v5, v5], axis=1)
    v7 = jnp.max(v6, axis=0)
    v8 = v7.T
    v9 = jax.nn.softmax(v8, axis=-1)
    v10 = v9 * 2.0  # expected-shape: v10=[1, d16, 4]
    v11 = jax.nn.gelu(v10)
    v12 = jnp.concatenate([v11, v11], axis=2)
    v13 = v12 * 0.5
