def nested_29(x: Float[Array, "b29 n29 d29"], w: Float[Array, "d29 d29"]):
    def level1(t):
        u = t * 2.0

        def level2(v):
            return v + 1.0

        return level2(u)

    y = level1(x)  # expected-shape: y=[b29, n29, d29]
    c = x[:, :4]  # expected-shape: c=[b29, 4, d29]
    h = c.sum(axis=1)  # expected-shape: h=[b29, d29]
    top, ix = jax.lax.top_k(y, 3)  # expected-shape: top=[b29, n29, 3]; ix=[b29, n29, 3]
    z = y @ w  # expected-shape: z=[b29, n29, d29]
    return y, h, z


def scan_ema_30(xs: Float[Array, "t30 32"], h0: Float[Array, "32"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[32]; ys=[t30, 32]
    total = ys.sum(axis=0)  # expected-shape: total=[32]
    scaled = ys / 2.0  # expected-shape: scaled=[t30, 32]
    return last, scaled


def vmap_rows_30(x: Float[Array, "b30 t30 32"], w: Float[Array, "32 12"]):
    y = jax.vmap(lambda r: r @ w)(x)
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b30, t30, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b30, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


def unpack_31(x: Float[Array, "b31 n31 36"], m: Float[Array, "12 24"]):
    q, k, v = jnp.split(x, 3, axis=-1)  # expected-shape: q=[b31, n31, 12]; k=[b31, n31, 12]; v=[b31, n31, 12]
    qk = jnp.einsum('bnd,bmd->bnm', q, k)  # expected-shape: qk=[b31, n31, n31]
    u, sv, vh = jnp.linalg.svd(m)  # expected-shape: u=[12, 12]; sv=[12]; vh=[24, 24]
    top, ti = jax.lax.top_k(v, 2)  # expected-shape: top=[b31, n31, 2]; ti=[b31, n31, 2]
