        r0 = F.relu(n0)  # expected-shape: r0=[b34, 8, 62, 62]
        p0 = self.pool(r0)  # expected-shape: p0=[b34, 8, 31, 31]
        c1 = self.conv1(p0)  # expected-shape: c1=[b34, 48, 27, 27]
        n1 = self.bn1(c1)  # expected-shape: n1=[b34, 48, 27, 27]
        r1 = F.relu(n1)  # expected-shape: r1=[b34, 48, 27, 27]
        p1 = self.pool(r1)  # expected-shape: p1=[b34, 48, 13, 13]
        c2 = self.conv2(p1)  # expected-shape: c2=[b34, 64, 13, 13]
        n2 = self.bn2(c2)  # expected-shape: n2=[b34, 64, 13, 13]
        r2 = F.relu(n2)  # expected-shape: r2=[b34, 64, 13, 13]
        p2 = self.pool(r2)  # expected-shape: p2=[b34, 64, 6, 6]
        f = p2.flatten(1)  # expected-shape: f=[b34, 2304]
        logits = self.fc(f)  # expected-shape: logits=[b34, 10]
        return logits


