def einops_soup_44(x: Float[Array, "b44 n44 32"]):
    e0 = rearrange(x, "b n d -> (b n) d")  # expected-shape: e0=[b44*n44, 32]
    e1 = reduce(x, "b n d -> b", "max")  # expected-shape: e1=[b44]
    e2 = reduce(x, "b n d -> b d", "mean")  # expected-shape: e2=[b44, 32]
    e3 = reduce(x, "b n d -> n", "sum")  # expected-shape: e3=[n44]
    return e0


def cross_45(x: Float[Array, "b45 d45"], w: Float[Array, "d45 k45"], seq: Float[Array, "b45 n45 d45"]):
    a = norm_rows_5(x)  # expected-shape: a=[b45, d45]
    p = project_5(a, w)  # expected-shape: p=[b45, k45]
    c = pool_seq_5(seq)  # expected-shape: c=[b45, d45]
    q = project_5(c, w)  # expected-shape: q=[b45, k45]
    sc = attend_5(seq, seq)  # expected-shape: sc=[b45, n45, n45]
    s2 = scale_rows_5(sc)  # expected-shape: s2=[b45, n45, n45]
    return p, q, s2


