class Attn52(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(48, 144)
        self.proj = nn.Linear(48, 48)
        self.norm = nn.LayerNorm(48)

    def forward(self, x: Float[Array, "b52 s52 48"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b52, s52, 144]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b52, s52, 48]; k=[b52, s52, 48]; v=[b52, s52, 48]
        q = q.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: q=[b52, s52, 8, 6]
        k = k.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: k=[b52, s52, 8, 6]
        v = v.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: v=[b52, s52, 8, 6]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b52, 8, s52, 6]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b52, 8, 6, s52]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b52, 8, s52, 6]
        scores = q @ k  # expected-shape: scores=[b52, 8, s52, s52]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b52, 8, s52, s52]
        ctx = attn @ v  # expected-shape: ctx=[b52, 8, s52, 6]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b52, s52, 8, 6]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 48)  # expected-shape: ctx=[b52, s52, 48]
        out = self.proj(ctx)  # expected-shape: out=[b52, s52, 48]
        out = self.norm(out + x)  # expected-shape: out=[b52, s52, 48]
        return out


class AttnBlock52(Attn52):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(48, 192)
        self.fc2 = nn.Linear(192, 48)

    def forward(self, x: Float[Array, "b52 s52 48"]):
        h = self.norm(x)  # expected-shape: h=[b52, s52, 48]
        h = self.fc1(h)  # expected-shape: h=[b52, s52, 192]
        h = F.gelu(h)  # expected-shape: h=[b52, s52, 192]
        h = self.fc2(h)  # expected-shape: h=[b52, s52, 48]
        qkv2 = self.qkv(h)  # expected-shape: qkv2=[b52, s52, 144]
        o = self.proj(h) + x  # expected-shape: o=[b52, s52, 48]
        return o


def mm_helper_53(a, w):
    c = a @ w
    return c


def lazy_user_53(x: Float[Array, "b53 n53 d53"], w: Float[Array, "d53 k53"], v: Float[Array, "d53 7"]):
    p = mm_helper_53(x, w)  # expected-shape: p=[b53, n53, k53]
    q = mm_helper_53(x, v)  # expected-shape: q=[b53, n53, 7]
    r = p.sum(axis=1)  # expected-shape: r=[b53, k53]
    return p, q, r


class ConvNet54(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(1, 8, 5, stride=2, padding=2)
        self.bn0 = nn.BatchNorm2d(8)
        self.conv1 = nn.Conv2d(8, 32, 5, stride=1, padding=2)
        self.bn1 = nn.BatchNorm2d(32)
        self.conv2 = nn.Conv2d(32, 96, 3, stride=1, padding=0)
        self.bn2 = nn.BatchNorm2d(96)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(96, 100)

    def forward(self, x: Float[Array, "b54 1 32 32"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b54, 8, 16, 16]
        n0 = self.bn0(c0)  # expected-shape: n0=[b54, 8, 16, 16]
        r0 = F.relu(n0)  # expected-shape: r0=[b54, 8, 16, 16]
