class Attn66(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(48, 144)
        self.proj = nn.Linear(48, 48)
        self.norm = nn.LayerNorm(48)

    def forward(self, x: Float[Array, "b66 s66 48"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b66, s66, 144]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b66, s66, 48]; k=[b66, s66, 48]; v=[b66, s66, 48]
        q = q.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: q=[b66, s66, 8, 6]
        k = k.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: k=[b66, s66, 8, 6]
        v = v.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: v=[b66, s66, 8, 6]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b66, 8, s66, 6]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b66, 8, 6, s66]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b66, 8, s66, 6]
        scores = q @ k  # expected-shape: scores=[b66, 8, s66, s66]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b66, 8, s66, s66]
        ctx = attn @ v  # expected-shape: ctx=[b66, 8, s66, 6]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b66, s66, 8, 6]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 48)  # expected-shape: ctx=[b66, s66, 48]
        out = self.proj(ctx)  # expected-shape: out=[b66, s66, 48]
        out = self.norm(out + x)  # expected-shape: out=[b66, s66, 48]
        return out


class AttnBlock66(Attn66):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(48, 192)
        self.fc2 = nn.Linear(192, 48)

    def forward(self, x: Float[Array, "b66 s66 48"]):
        h = self.norm(x)  # expected-shape: h=[b66, s66, 48]
        h = self.fc1(h)  # expected-shape: h=[b66, s66, 192]
        h = F.gelu(h)  # expected-shape: h=[b66, s66, 192]
        h = self.fc2(h)  # expected-shape: h=[b66, s66, 48]
        qkv2 = self.qkv(h)  # expected-shape: qkv2=[b66, s66, 144]
        o = self.proj(h) + x  # expected-shape: o=[b66, s66, 48]
        return o


