def branchy_90(x: Float[Array, "b90 n90 d90"], y: Float[Array, "b90 n90 d90"], flag90: bool):
    z = x + y  # expected-shape: z=[b90, n90, d90]
    if flag90:
        w = z.sum(axis=-1)  # expected-shape: w=[b90, n90]
    elif not flag90:
        w = z.mean(axis=1)  # expected-shape: w=[b90, d90]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b90, n90]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b90, n90, d90]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n90, d90]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n90, d90]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


class SeqModel91(nn.Module):
    def __init__(self):
        super().__init__()
        self.emb = nn.Embedding(5000, 32)
        self.gru = nn.GRU(32, 64, batch_first=True)
        self.head = nn.Linear(64, 5000)
        self.mha = nn.MultiheadAttention(64, 4)

    def forward(self, ids: Float[Array, "b91 s91"]):
        e = self.emb(ids)  # expected-shape: e=[b91, s91, 32]
        out, _ = self.gru(e)  # expected-shape: out=[b91, s91, 64]
        att, w = self.mha(out, out, out)  # expected-shape: att=[b91, s91, 64]; w=[b91, s91, s91]
        logits = self.head(att)  # expected-shape: logits=[b91, s91, 5000]
        pooled = logits.mean(dim=1)  # expected-shape: pooled=[b91, 5000]
        last = out[:, -1, :]  # expected-shape: last=[b91, 64]
        tops, idx = logits.topk(5, dim=-1)  # expected-shape: tops=[b91, s91, 5]; idx=[b91, s91, 5]
        return logits


def einops_soup_92(x: Float[Array, "b92 n92 64"]):
    e0 = reduce(x, "b n d -> b", "max")  # expected-shape: e0=[b92]
    e1 = rearrange(x, "b n d -> b (n d)")  # expected-shape: e1=[b92, n92*64]
    e2 = rearrange(x, "b n d -> d n b")  # expected-shape: e2=[64, n92, b92]
    e3 = rearrange(x, "b n d -> (b n) d")  # expected-shape: e3=[b92*n92, 64]
    e4 = rearrange(x, "b n (h e) -> b h n e", h=4)  # expected-shape: e4=[b92, 4, n92, 16]
    return e0


class ConvNet93(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(3, 16, 3, stride=1, padding=1)
        self.bn0 = nn.BatchNorm2d(16)
        self.conv1 = nn.Conv2d(16, 32, 5, stride=1, padding=0)
        self.bn1 = nn.BatchNorm2d(32)
        self.conv2 = nn.Conv2d(32, 96, 3, stride=2, padding=1)
        self.bn2 = nn.BatchNorm2d(96)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(96, 10)

    def forward(self, x: Float[Array, "b93 3 28 28"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b93, 16, 28, 28]
        n0 = self.bn0(c0)  # expected-shape: n0=[b93, 16, 28, 28]
        r0 = F.relu(n0)  # expected-shape: r0=[b93, 16, 28, 28]
        p0 = self.pool(r0)  # expected-shape: p0=[b93, 16, 14, 14]
        c1 = self.conv1(p0)  # expected-shape: c1=[b93, 32, 10, 10]
        n1 = self.bn1(c1)  # expected-shape: n1=[b93, 32, 10, 10]
        r1 = F.relu(n1)  # expected-shape: r1=[b93, 32, 10, 10]
        p1 = self.pool(r1)  # expected-shape: p1=[b93, 32, 5, 5]
        c2 = self.conv2(p1)  # expected-shape: c2=[b93, 96, 3, 3]
        n2 = self.bn2(c2)  # expected-shape: n2=[b93, 96, 3, 3]
        r2 = F.relu(n2)  # expected-shape: r2=[b93, 96, 3, 3]
        p2 = self.pool(r2)  # expected-shape: p2=[b93, 96, 1, 1]
        f = p2.flatten(1)  # expected-shape: f=[b93, 96]
        logits = self.fc(f)  # expected-shape: logits=[b93, 10]
        return logits


def cross_94(x: Float[Array, "b94 d94"], w: Float[Array, "d94 k94"], seq: Float[Array, "b94 n94 d94"]):
    a = norm_rows_14(x)  # expected-shape: a=[b94, d94]
    p = project_14(a, w)  # expected-shape: p=[b94, k94]
    c = pool_seq_14(seq)  # expected-shape: c=[b94, d94]
    q = project_14(c, w)  # expected-shape: q=[b94, k94]
    sc = attend_14(seq, seq)  # expected-shape: sc=[b94, n94, n94]
    s2 = scale_rows_14(sc)  # expected-shape: s2=[b94, n94, n94]
    return p, q, s2


