    z = x + y  # expected-shape: z=[b101, n101, d101]
    if flag101:
        w = z.sum(axis=-1)  # expected-shape: w=[b101, n101]
    elif not flag101:
        w = z.mean(axis=1)  # expected-shape: w=[b101, d101]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b101, n101]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b101, n101, d101]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n101, d101]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n101, d101]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


