def nested_104(x: Float[Array, "b104 n104 d104"], w: Float[Array, "d104 d104"]):
    def level1(t):
        u = t * 2.0

        def level2(v):
            return v + 1.0

        return level2(u)

    y = level1(x)  # expected-shape: y=[b104, n104, d104]
    c = x[:, :4]  # expected-shape: c=[b104, 4, d104]
    h = c.sum(axis=1)  # expected-shape: h=[b104, d104]
    top, ix = jax.lax.top_k(y, 3)  # expected-shape: top=[b104, n104, 3]; ix=[b104, n104, 3]
    z = y @ w  # expected-shape: z=[b104, n104, d104]
    return y, h, z


