def scan_ema_109(xs: Float[Array, "t109 32"], h0: Float[Array, "32"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[32]; ys=[t109, 32]
    total = ys.sum(axis=0)  # expected-shape: total=[32]
    scaled = ys / 2.0  # expected-shape: scaled=[t109, 32]
    return last, scaled


