class Attn136(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(32, 96)
        self.proj = nn.Linear(32, 32)
        self.norm = nn.LayerNorm(32)

    def forward(self, x: Float[Array, "b136 s136 32"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b136, s136, 96]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b136, s136, 32]; k=[b136, s136, 32]; v=[b136, s136, 32]
        q = q.reshape(x.shape[0], x.shape[1], 8, 4)  # expected-shape: q=[b136, s136, 8, 4]
        k = k.reshape(x.shape[0], x.shape[1], 8, 4)  # expected-shape: k=[b136, s136, 8, 4]
        v = v.reshape(x.shape[0], x.shape[1], 8, 4)  # expected-shape: v=[b136, s136, 8, 4]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b136, 8, s136, 4]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b136, 8, 4, s136]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b136, 8, s136, 4]
        scores = q @ k  # expected-shape: scores=[b136, 8, s136, s136]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b136, 8, s136, s136]
        ctx = attn @ v  # expected-shape: ctx=[b136, 8, s136, 4]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b136, s136, 8, 4]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 32)  # expected-shape: ctx=[b136, s136, 32]
        out = self.proj(ctx)  # expected-shape: out=[b136, s136, 32]
        out = self.norm(out + x)  # expected-shape: out=[b136, s136, 32]
        return out


