def cross_143(x: Float[Array, "b143 d143"], w: Float[Array, "d143 k143"], seq: Float[Array, "b143 n143 d143"]):
    a = norm_rows_3(x)  # expected-shape: a=[b143, d143]
    p = project_3(a, w)  # expected-shape: p=[b143, k143]
    c = pool_seq_3(seq)  # expected-shape: c=[b143, d143]
    q = project_3(c, w)  # expected-shape: q=[b143, k143]
    sc = attend_3(seq, seq)  # expected-shape: sc=[b143, n143, n143]
    s2 = scale_rows_3(sc)  # expected-shape: s2=[b143, n143, n143]
    return p, q, s2


class Attn144(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(96, 288)
        self.proj = nn.Linear(96, 96)
        self.norm = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b144 s144 96"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b144, s144, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b144, s144, 96]; k=[b144, s144, 96]; v=[b144, s144, 96]
        q = q.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: q=[b144, s144, 4, 24]
        k = k.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: k=[b144, s144, 4, 24]
        v = v.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: v=[b144, s144, 4, 24]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b144, 4, s144, 24]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b144, 4, 24, s144]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b144, 4, s144, 24]
        scores = q @ k  # expected-shape: scores=[b144, 4, s144, s144]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b144, 4, s144, s144]
        ctx = attn @ v  # expected-shape: ctx=[b144, 4, s144, 24]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b144, s144, 4, 24]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b144, s144, 96]
        out = self.proj(ctx)  # expected-shape: out=[b144, s144, 96]
        out = self.norm(out + x)  # expected-shape: out=[b144, s144, 96]
        return out


class AttnBlock144(Attn144):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(96, 384)
        self.fc2 = nn.Linear(384, 96)

    def forward(self, x: Float[Array, "b144 s144 96"]):
        h = self.norm(x)  # expected-shape: h=[b144, s144, 96]
        h = self.fc1(h)  # expected-shape: h=[b144, s144, 384]
        h = F.gelu(h)  # expected-shape: h=[b144, s144, 384]
        h = self.fc2(h)  # expected-shape: h=[b144, s144, 96]
        qkv2 = self.qkv(h)  # expected-shape: qkv2=[b144, s144, 288]
        o = self.proj(h) + x  # expected-shape: o=[b144, s144, 96]
        return o


def first_col_145(t):
    return t[:, 0]


def lazy_user_145(x: Float[Array, "b145 n145 d145"], y: Float[Array, "n145 d145"]):
    f1 = first_col_145(x)  # expected-shape: f1=[b145, d145]
    f2 = first_col_145(y)  # expected-shape: f2=[n145]
    f3 = f1 * 2.0 + f1  # expected-shape: f3=[b145, d145]
    return f1, f2, f3


def einops_soup_146(x: Float[Array, "b146 n146 32"]):
    e0 = rearrange(x, "b n d -> b (n d)")  # expected-shape: e0=[b146, n146*32]
    e1 = repeat(x, "b n d -> b n d k", k=3)  # expected-shape: e1=[b146, n146, 32, 3]
    e2 = repeat(x, "b n d -> r b n d", r=2)  # expected-shape: e2=[2, b146, n146, 32]
    e3 = rearrange(x, "b n d -> d n b")  # expected-shape: e3=[32, n146, b146]
    e4 = rearrange(x, "b n (h e) -> b h n e", h=4)  # expected-shape: e4=[b146, 4, n146, 8]
    e5 = reduce(x, "b n d -> n", "sum")  # expected-shape: e5=[n146]
    return e0


