class Attn150(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(128, 384)
        self.proj = nn.Linear(128, 128)
        self.norm = nn.LayerNorm(128)

    def forward(self, x: Float[Array, "b150 s150 128"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b150, s150, 384]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b150, s150, 128]; k=[b150, s150, 128]; v=[b150, s150, 128]
        q = q.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: q=[b150, s150, 8, 16]
        k = k.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: k=[b150, s150, 8, 16]
        v = v.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: v=[b150, s150, 8, 16]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b150, 8, s150, 16]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b150, 8, 16, s150]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b150, 8, s150, 16]
        scores = q @ k  # expected-shape: scores=[b150, 8, s150, s150]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b150, 8, s150, s150]
        ctx = attn @ v  # expected-shape: ctx=[b150, 8, s150, 16]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b150, s150, 8, 16]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 128)  # expected-shape: ctx=[b150, s150, 128]
        out = self.proj(ctx)  # expected-shape: out=[b150, s150, 128]
        out = self.norm(out + x)  # expected-shape: out=[b150, s150, 128]
        return out


