def scan_ema_154(xs: Float[Array, "t154 32"], h0: Float[Array, "32"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[32]; ys=[t154, 32]
    total = ys.sum(axis=0)  # expected-shape: total=[32]
    scaled = ys / 2.0  # expected-shape: scaled=[t154, 32]
    return last, scaled


def vmap_rows_154(x: Float[Array, "b154 t154 32"], w: Float[Array, "32 12"]):
    y = jax.vmap(lambda r: r @ w)(x)
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b154, t154, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b154, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


