def nested_192(x: Float[Array, "b192 n192 d192"], w: Float[Array, "d192 d192"]):
    def level1(t):
        u = t * 2.0

        def level2(v):
            return v + 1.0

        return level2(u)

    y = level1(x)  # expected-shape: y=[b192, n192, d192]
    c = x[:, :4]  # expected-shape: c=[b192, 4, d192]
    h = c.sum(axis=1)  # expected-shape: h=[b192, d192]
    top, ix = jax.lax.top_k(y, 3)  # expected-shape: top=[b192, n192, 3]; ix=[b192, n192, 3]
    z = y @ w  # expected-shape: z=[b192, n192, d192]
    return y, h, z


