def scan_ema_203(xs: Float[Array, "t203 8"], h0: Float[Array, "8"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[8]; ys=[t203, 8]
    total = ys.sum(axis=0)  # expected-shape: total=[8]
    scaled = ys / 2.0  # expected-shape: scaled=[t203, 8]
    return last, scaled


