    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b203, t203, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b203, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


