class Attn228(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(48, 144)
        self.proj = nn.Linear(48, 48)
        self.norm = nn.LayerNorm(48)

    def forward(self, x: Float[Array, "b228 s228 48"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b228, s228, 144]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b228, s228, 48]; k=[b228, s228, 48]; v=[b228, s228, 48]
        q = q.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: q=[b228, s228, 8, 6]
        k = k.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: k=[b228, s228, 8, 6]
        v = v.reshape(x.shape[0], x.shape[1], 8, 6)  # expected-shape: v=[b228, s228, 8, 6]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b228, 8, s228, 6]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b228, 8, 6, s228]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b228, 8, s228, 6]
        scores = q @ k  # expected-shape: scores=[b228, 8, s228, s228]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b228, 8, s228, s228]
        ctx = attn @ v  # expected-shape: ctx=[b228, 8, s228, 6]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b228, s228, 8, 6]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 48)  # expected-shape: ctx=[b228, s228, 48]
        out = self.proj(ctx)  # expected-shape: out=[b228, s228, 48]
        out = self.norm(out + x)  # expected-shape: out=[b228, s228, 48]
        return out


