def scan_ema_232(xs: Float[Array, "t232 32"], h0: Float[Array, "32"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[32]; ys=[t232, 32]
    total = ys.sum(axis=0)  # expected-shape: total=[32]
    scaled = ys / 2.0  # expected-shape: scaled=[t232, 32]
    return last, scaled


