        c1 = self.conv1(p0)  # expected-shape: c1=[b243, 48, 4, 4]
        n1 = self.bn1(c1)  # expected-shape: n1=[b243, 48, 4, 4]
        r1 = F.relu(n1)  # expected-shape: r1=[b243, 48, 4, 4]
        p1 = self.pool(r1)  # expected-shape: p1=[b243, 48, 2, 2]
        c2 = self.conv2(p1)  # expected-shape: c2=[b243, 64, 2, 2]
        n2 = self.bn2(c2)  # expected-shape: n2=[b243, 64, 2, 2]
