def branchy_255(x: Float[Array, "b255 n255 d255"], y: Float[Array, "b255 n255 d255"], flag255: bool):
    z = x + y  # expected-shape: z=[b255, n255, d255]
    if flag255:
        w = z.sum(axis=-1)  # expected-shape: w=[b255, n255]
    elif not flag255:
        w = z.mean(axis=1)  # expected-shape: w=[b255, d255]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b255, n255]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b255, n255, d255]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n255, d255]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n255, d255]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


class Attn256(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(64, 192)
        self.proj = nn.Linear(64, 64)
        self.norm = nn.LayerNorm(64)

    def forward(self, x: Float[Array, "b256 s256 64"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b256, s256, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b256, s256, 64]; k=[b256, s256, 64]; v=[b256, s256, 64]
        q = q.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: q=[b256, s256, 2, 32]
        k = k.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: k=[b256, s256, 2, 32]
        v = v.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: v=[b256, s256, 2, 32]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b256, 2, s256, 32]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b256, 2, 32, s256]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b256, 2, s256, 32]
        scores = q @ k  # expected-shape: scores=[b256, 2, s256, s256]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b256, 2, s256, s256]
        ctx = attn @ v  # expected-shape: ctx=[b256, 2, s256, 32]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b256, s256, 2, 32]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b256, s256, 64]
        out = self.proj(ctx)  # expected-shape: out=[b256, s256, 64]
        out = self.norm(out + x)  # expected-shape: out=[b256, s256, 64]
        return out


class AttnBlock256(Attn256):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(64, 256)
        self.fc2 = nn.Linear(256, 64)

    def forward(self, x: Float[Array, "b256 s256 64"]):
        h = self.norm(x)  # expected-shape: h=[b256, s256, 64]
        h = self.fc1(h)  # expected-shape: h=[b256, s256, 256]
        h = F.gelu(h)  # expected-shape: h=[b256, s256, 256]
        h = self.fc2(h)  # expected-shape: h=[b256, s256, 64]
        qkv2 = self.qkv(h)  # expected-shape: qkv2=[b256, s256, 192]
        o = self.proj(h) + x  # expected-shape: o=[b256, s256, 64]
        return o


def einops_soup_257(x: Float[Array, "b257 n257 32"]):
    e0 = rearrange(x, "b n d -> (b n) d")  # expected-shape: e0=[b257*n257, 32]
    e1 = reduce(x, "b n d -> b d", "mean")  # expected-shape: e1=[b257, 32]
    e2 = repeat(x, "b n d -> r b n d", r=2)  # expected-shape: e2=[2, b257, n257, 32]
    e3 = repeat(x, "b n d -> b n d k", k=3)  # expected-shape: e3=[b257, n257, 32, 3]
    e4 = rearrange(x, "b n d -> b (n d)")  # expected-shape: e4=[b257, n257*32]
    e5 = rearrange(x, "b n (h e) -> b h n e", h=4)  # expected-shape: e5=[b257, 4, n257, 8]
    e6 = reduce(x, "b n d -> n", "sum")  # expected-shape: e6=[n257]
    return e0


def inner_258(t):
    return t * 3.0


def outer_258(t):
    w = inner_258(t)
    s = w.mean(axis=0)
    return s


def lazy_user_258(x: Float[Array, "b258 n258 d258"], y: Float[Array, "n258 d258"]):
    a = outer_258(x)  # expected-shape: a=[n258, d258]
    c = outer_258(y)  # expected-shape: c=[d258]
    e = inner_258(y) + y  # expected-shape: e=[n258, d258]
    return a, c, e


