def scan_ema_261(xs: Float[Array, "t261 16"], h0: Float[Array, "16"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[16]; ys=[t261, 16]
    total = ys.sum(axis=0)  # expected-shape: total=[16]
    scaled = ys / 2.0  # expected-shape: scaled=[t261, 16]
    return last, scaled


def vmap_rows_261(x: Float[Array, "b261 t261 16"], w: Float[Array, "16 12"]):
    y = jax.vmap(lambda r: r @ w)(x)
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b261, t261, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b261, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


def nested_262(x: Float[Array, "b262 n262 d262"], w: Float[Array, "d262 d262"]):
    def level1(t):
        u = t * 2.0

        def level2(v):
            return v + 1.0

        return level2(u)

    y = level1(x)  # expected-shape: y=[b262, n262, d262]
    c = x[:, :4]  # expected-shape: c=[b262, 4, d262]
    h = c.sum(axis=1)  # expected-shape: h=[b262, d262]
    top, ix = jax.lax.top_k(y, 3)  # expected-shape: top=[b262, n262, 3]; ix=[b262, n262, 3]
    z = y @ w  # expected-shape: z=[b262, n262, d262]
    return y, h, z


