class Attn290(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(64, 192)
        self.proj = nn.Linear(64, 64)
        self.norm = nn.LayerNorm(64)

    def forward(self, x: Float[Array, "b290 s290 64"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b290, s290, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b290, s290, 64]; k=[b290, s290, 64]; v=[b290, s290, 64]
        q = q.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: q=[b290, s290, 8, 8]
        k = k.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: k=[b290, s290, 8, 8]
        v = v.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: v=[b290, s290, 8, 8]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b290, 8, s290, 8]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b290, 8, 8, s290]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b290, 8, s290, 8]
        scores = q @ k  # expected-shape: scores=[b290, 8, s290, s290]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b290, 8, s290, s290]
        ctx = attn @ v  # expected-shape: ctx=[b290, 8, s290, 8]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b290, s290, 8, 8]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b290, s290, 64]
        out = self.proj(ctx)  # expected-shape: out=[b290, s290, 64]
        out = self.norm(out + x)  # expected-shape: out=[b290, s290, 64]
        return out


class AttnBlock290(Attn290):
    def __init__(self):
        super().__init__()
