def reduce_last_311(t):
    u = t * 2.0
    return u.sum(axis=-1)


def lazy_user_311(x: Float[Array, "b311 n311 d311"], y: Float[Array, "n311 d311"], z: Float[Array, "k311"]):
    r1 = reduce_last_311(x)  # expected-shape: r1=[b311, n311]
    r2 = reduce_last_311(y)  # expected-shape: r2=[n311]
    r3 = reduce_last_311(z)  # expected-shape: r3=[]
    r4 = reduce_last_311(x) + 1.0  # expected-shape: r4=[b311, n311]
    return r1, r2, r3, r4


def scan_ema_312(xs: Float[Array, "t312 16"], h0: Float[Array, "16"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[16]; ys=[t312, 16]
    total = ys.sum(axis=0)  # expected-shape: total=[16]
    scaled = ys / 2.0  # expected-shape: scaled=[t312, 16]
    return last, scaled


def vmap_rows_312(x: Float[Array, "b312 t312 16"], w: Float[Array, "16 12"]):
    y = jax.vmap(lambda r: r @ w)(x)
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b312, t312, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b312, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


@dataclass
class Config313:
    dim: int = 96
    heads: int = 4
    name: str = "cfg"

    @property
    def head_dim(self) -> int:
        return self.dim // self.heads


def scalar_math_313(a: float, b: int = 313) -> float:
    """Plain Python with no tensors: the analyzer must skip it."""
    total = 0.0
    for k in range(b):
        total += math.sqrt(k + a) * (k % 3)
    values = [k * 2 for k in range(10) if k % 2 == 0]
    table = {k: v for k, v in zip(range(5), values)}
    if total > 10 and len(table) > 2:
        total = -total
    return total


def cross_314(x: Float[Array, "b314 d314"], w: Float[Array, "d314 k314"], seq: Float[Array, "b314 n314 d314"]):
    a = norm_rows_14(x)  # expected-shape: a=[b314, d314]
    p = project_14(a, w)  # expected-shape: p=[b314, k314]
    c = pool_seq_14(seq)  # expected-shape: c=[b314, d314]
    q = project_14(c, w)  # expected-shape: q=[b314, k314]
    sc = attend_14(seq, seq)  # expected-shape: sc=[b314, n314, n314]
