def unpack_336(x: Float[Array, "b336 n336 48"], m: Float[Array, "16 32"]):
    q, k, v = jnp.split(x, 3, axis=-1)  # expected-shape: q=[b336, n336, 16]; k=[b336, n336, 16]; v=[b336, n336, 16]
    qk = jnp.einsum('bnd,bmd->bnm', q, k)  # expected-shape: qk=[b336, n336, n336]
    u, sv, vh = jnp.linalg.svd(m)  # expected-shape: u=[16, 16]; sv=[16]; vh=[32, 32]
    top, ti = jax.lax.top_k(v, 2)  # expected-shape: top=[b336, n336, 2]; ti=[b336, n336, 2]
    c1, c2 = jnp.split(m, 2, axis=1)  # expected-shape: c1=[16, 16]; c2=[16, 16]
    return qk, u, c1


def branchy_337(x: Float[Array, "b337 n337 d337"], y: Float[Array, "b337 n337 d337"], flag337: bool):
    z = x + y  # expected-shape: z=[b337, n337, d337]
    if flag337:
        w = z.sum(axis=-1)  # expected-shape: w=[b337, n337]
    elif not flag337:
        w = z.mean(axis=1)  # expected-shape: w=[b337, d337]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b337, n337]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b337, n337, d337]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n337, d337]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n337, d337]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


