class Attn350(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(64, 192)
        self.proj = nn.Linear(64, 64)
        self.norm = nn.LayerNorm(64)

    def forward(self, x: Float[Array, "b350 s350 64"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b350, s350, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b350, s350, 64]; k=[b350, s350, 64]; v=[b350, s350, 64]
        q = q.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: q=[b350, s350, 8, 8]
        k = k.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: k=[b350, s350, 8, 8]
        v = v.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: v=[b350, s350, 8, 8]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b350, 8, s350, 8]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b350, 8, 8, s350]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b350, 8, s350, 8]
        scores = q @ k  # expected-shape: scores=[b350, 8, s350, s350]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b350, 8, s350, s350]
        ctx = attn @ v  # expected-shape: ctx=[b350, 8, s350, 8]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b350, s350, 8, 8]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b350, s350, 64]
        out = self.proj(ctx)  # expected-shape: out=[b350, s350, 64]
        out = self.norm(out + x)  # expected-shape: out=[b350, s350, 64]
        return out


class AttnBlock350(Attn350):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(64, 256)
        self.fc2 = nn.Linear(256, 64)

    def forward(self, x: Float[Array, "b350 s350 64"]):
        h = self.norm(x)  # expected-shape: h=[b350, s350, 64]
        h = self.fc1(h)  # expected-shape: h=[b350, s350, 256]
        h = F.gelu(h)  # expected-shape: h=[b350, s350, 256]
        h = self.fc2(h)  # expected-shape: h=[b350, s350, 64]
        qkv2 = self.qkv(h)  # expected-shape: qkv2=[b350, s350, 192]
        o = self.proj(h) + x  # expected-shape: o=[b350, s350, 64]
        return o


