def scan_ema_352(xs: Float[Array, "t352 16"], h0: Float[Array, "16"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[16]; ys=[t352, 16]
    total = ys.sum(axis=0)  # expected-shape: total=[16]
