    qk = jnp.einsum('bnd,bmd->bnm', q, k)  # expected-shape: qk=[b356, n356, n356]
    u, sv, vh = jnp.linalg.svd(m)  # expected-shape: u=[16, 16]; sv=[16]; vh=[32, 32]
    top, ti = jax.lax.top_k(v, 2)  # expected-shape: top=[b356, n356, 2]; ti=[b356, n356, 2]
    c1, c2 = jnp.split(m, 2, axis=1)  # expected-shape: c1=[16, 16]; c2=[16, 16]
    return qk, u, c1


