def einops_soup_358(x: Float[Array, "b358 n358 16"]):
    e0 = reduce(x, "b n d -> b", "max")  # expected-shape: e0=[b358]
    e1 = reduce(x, "b n d -> n", "sum")  # expected-shape: e1=[n358]
    e2 = reduce(x, "b n d -> b d", "mean")  # expected-shape: e2=[b358, 16]
    e3 = rearrange(x, "b n (h e) -> b h n e", h=4)  # expected-shape: e3=[b358, 4, n358, 4]
    e4 = rearrange(x, "b n d -> b (n d)")  # expected-shape: e4=[b358, n358*16]
    e5 = repeat(x, "b n d -> r b n d", r=2)  # expected-shape: e5=[2, b358, n358, 16]
    return e0


