class Attn362(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(128, 384)
        self.proj = nn.Linear(128, 128)
        self.norm = nn.LayerNorm(128)

    def forward(self, x: Float[Array, "b362 s362 128"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b362, s362, 384]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b362, s362, 128]; k=[b362, s362, 128]; v=[b362, s362, 128]
        q = q.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: q=[b362, s362, 8, 16]
        k = k.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: k=[b362, s362, 8, 16]
        v = v.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: v=[b362, s362, 8, 16]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b362, 8, s362, 16]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b362, 8, 16, s362]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b362, 8, s362, 16]
        scores = q @ k  # expected-shape: scores=[b362, 8, s362, s362]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b362, 8, s362, s362]
        ctx = attn @ v  # expected-shape: ctx=[b362, 8, s362, 16]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b362, s362, 8, 16]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 128)  # expected-shape: ctx=[b362, s362, 128]
        out = self.proj(ctx)  # expected-shape: out=[b362, s362, 128]
        out = self.norm(out + x)  # expected-shape: out=[b362, s362, 128]
        return out


