def branchy_366(x: Float[Array, "b366 n366 d366"], y: Float[Array, "b366 n366 d366"], flag366: bool):
    z = x + y  # expected-shape: z=[b366, n366, d366]
    if flag366:
        w = z.sum(axis=-1)  # expected-shape: w=[b366, n366]
    elif not flag366:
        w = z.mean(axis=1)  # expected-shape: w=[b366, d366]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b366, n366]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b366, n366, d366]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n366, d366]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n366, d366]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


