class Attn429(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_429 = nn.Linear(96, 288)
        self.proj_429 = nn.Linear(96, 96)
        self.norm_429 = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b429 s429 96"]):
        qkv = self.qkv_429(x)  # expected-shape: qkv=[b429, s429, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b429, s429, 96]; k=[b429, s429, 96]; v=[b429, s429, 96]
        q = q.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: q=[b429, s429, 8, 12]
        k = k.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: k=[b429, s429, 8, 12]
        v = v.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: v=[b429, s429, 8, 12]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b429, 8, s429, 12]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b429, 8, 12, s429]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b429, 8, s429, 12]
        scores = q @ k  # expected-shape: scores=[b429, 8, s429, s429]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b429, 8, s429, s429]
        ctx = attn @ v  # expected-shape: ctx=[b429, 8, s429, 12]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b429, s429, 8, 12]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b429, s429, 96]
        out = self.proj_429(ctx)  # expected-shape: out=[b429, s429, 96]
        out = self.norm_429(out + x)  # expected-shape: out=[b429, s429, 96]
        return out


class AttnBlock429(Attn429):
    def __init__(self):
        super().__init__()
        self.fc1_429 = nn.Linear(96, 384)
        self.fc2_429 = nn.Linear(384, 96)

    def forward(self, x: Float[Array, "b429 s429 96"]):
        h = self.norm_429(x)  # expected-shape: h=[b429, s429, 96]
        h = self.fc1_429(h)  # expected-shape: h=[b429, s429, 384]
        h = F.gelu(h)  # expected-shape: h=[b429, s429, 384]
        h = self.fc2_429(h)  # expected-shape: h=[b429, s429, 96]
        qkv2 = self.qkv_429(h)  # expected-shape: qkv2=[b429, s429, 288]
        o = self.proj_429(h) + x  # expected-shape: o=[b429, s429, 96]
        return o


def scan_ema_430(xs: Float[Array, "t430 8"], h0: Float[Array, "8"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[8]; ys=[t430, 8]
    total = ys.sum(axis=0)  # expected-shape: total=[8]
    scaled = ys / 2.0  # expected-shape: scaled=[t430, 8]
    return last, scaled


def vmap_rows_430(x: Float[Array, "b430 t430 8"], w: Float[Array, "8 12"]):
    y = jax.vmap(lambda r: r @ w)(x)
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b430, t430, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b430, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


