class ConvNet441(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(3, 16, 3, stride=1, padding=0)
        self.bn0 = nn.BatchNorm2d(16)
        self.conv1 = nn.Conv2d(16, 48, 5, stride=1, padding=0)
        self.bn1 = nn.BatchNorm2d(48)
        self.conv2 = nn.Conv2d(48, 64, 5, stride=1, padding=2)
        self.bn2 = nn.BatchNorm2d(64)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(2304, 10)

    def forward(self, x: Float[Array, "b441 3 64 64"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b441, 16, 62, 62]
        n0 = self.bn0(c0)  # expected-shape: n0=[b441, 16, 62, 62]
        r0 = F.relu(n0)  # expected-shape: r0=[b441, 16, 62, 62]
        p0 = self.pool(r0)  # expected-shape: p0=[b441, 16, 31, 31]
        c1 = self.conv1(p0)  # expected-shape: c1=[b441, 48, 27, 27]
        n1 = self.bn1(c1)  # expected-shape: n1=[b441, 48, 27, 27]
        r1 = F.relu(n1)  # expected-shape: r1=[b441, 48, 27, 27]
        p1 = self.pool(r1)  # expected-shape: p1=[b441, 48, 13, 13]
        c2 = self.conv2(p1)  # expected-shape: c2=[b441, 64, 13, 13]
        n2 = self.bn2(c2)  # expected-shape: n2=[b441, 64, 13, 13]
        r2 = F.relu(n2)  # expected-shape: r2=[b441, 64, 13, 13]
        p2 = self.pool(r2)  # expected-shape: p2=[b441, 64, 6, 6]
        f = p2.flatten(1)  # expected-shape: f=[b441, 2304]
        logits = self.fc(f)  # expected-shape: logits=[b441, 10]
        return logits


