class Attn445(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_445 = nn.Linear(32, 96)
        self.proj_445 = nn.Linear(32, 32)
        self.norm_445 = nn.LayerNorm(32)

    def forward(self, x: Float[Array, "b445 s445 32"]):
        qkv = self.qkv_445(x)  # expected-shape: qkv=[b445, s445, 96]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b445, s445, 32]; k=[b445, s445, 32]; v=[b445, s445, 32]
        q = q.reshape(x.shape[0], x.shape[1], 2, 16)  # expected-shape: q=[b445, s445, 2, 16]
        k = k.reshape(x.shape[0], x.shape[1], 2, 16)  # expected-shape: k=[b445, s445, 2, 16]
        v = v.reshape(x.shape[0], x.shape[1], 2, 16)  # expected-shape: v=[b445, s445, 2, 16]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b445, 2, s445, 16]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b445, 2, 16, s445]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b445, 2, s445, 16]
        scores = q @ k  # expected-shape: scores=[b445, 2, s445, s445]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b445, 2, s445, s445]
        ctx = attn @ v  # expected-shape: ctx=[b445, 2, s445, 16]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b445, s445, 2, 16]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 32)  # expected-shape: ctx=[b445, s445, 32]
        out = self.proj_445(ctx)  # expected-shape: out=[b445, s445, 32]
        out = self.norm_445(out + x)  # expected-shape: out=[b445, s445, 32]
        return out


