class Attn446(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(96, 288)
        self.proj = nn.Linear(96, 96)
        self.norm = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b446 s446 96"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b446, s446, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b446, s446, 96]; k=[b446, s446, 96]; v=[b446, s446, 96]
        q = q.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: q=[b446, s446, 4, 24]
        k = k.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: k=[b446, s446, 4, 24]
        v = v.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: v=[b446, s446, 4, 24]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b446, 4, s446, 24]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b446, 4, 24, s446]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b446, 4, s446, 24]
        scores = q @ k  # expected-shape: scores=[b446, 4, s446, s446]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b446, 4, s446, s446]
        ctx = attn @ v  # expected-shape: ctx=[b446, 4, s446, 24]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b446, s446, 4, 24]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b446, s446, 96]
        out = self.proj(ctx)  # expected-shape: out=[b446, s446, 96]
        out = self.norm(out + x)  # expected-shape: out=[b446, s446, 96]
        return out


