class Attn469(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_469 = nn.Linear(64, 192)
        self.proj_469 = nn.Linear(64, 64)
        self.norm_469 = nn.LayerNorm(64)

    def forward(self, x: Float[Array, "b469 s469 64"]):
        qkv = self.qkv_469(x)  # expected-shape: qkv=[b469, s469, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b469, s469, 64]; k=[b469, s469, 64]; v=[b469, s469, 64]
        q = q.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: q=[b469, s469, 8, 8]
        k = k.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: k=[b469, s469, 8, 8]
        v = v.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: v=[b469, s469, 8, 8]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b469, 8, s469, 8]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b469, 8, 8, s469]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b469, 8, s469, 8]
        scores = q @ k  # expected-shape: scores=[b469, 8, s469, s469]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b469, 8, s469, s469]
        ctx = attn @ v  # expected-shape: ctx=[b469, 8, s469, 8]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b469, s469, 8, 8]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b469, s469, 64]
        out = self.proj_469(ctx)  # expected-shape: out=[b469, s469, 64]
        out = self.norm_469(out + x)  # expected-shape: out=[b469, s469, 64]
        return out


class AttnBlock469(Attn469):
    def __init__(self):
        super().__init__()
        self.fc1_469 = nn.Linear(64, 256)
        self.fc2_469 = nn.Linear(256, 64)

    def forward(self, x: Float[Array, "b469 s469 64"]):
        h = self.norm_469(x)  # expected-shape: h=[b469, s469, 64]
        h = self.fc1_469(h)  # expected-shape: h=[b469, s469, 256]
        h = F.gelu(h)  # expected-shape: h=[b469, s469, 256]
        h = self.fc2_469(h)  # expected-shape: h=[b469, s469, 64]
        qkv2 = self.qkv_469(h)  # expected-shape: qkv2=[b469, s469, 192]
        o = self.proj_469(h) + x  # expected-shape: o=[b469, s469, 64]
        return o


