def nested_483(x: Float[Array, "b483 n483 d483"], w: Float[Array, "d483 d483"]):
    def level1(t):
        u = t * 2.0

        def level2(v):
            return v + 1.0

        return level2(u)

    y = level1(x)  # expected-shape: y=[b483, n483, d483]
    c = x[:, :4]  # expected-shape: c=[b483, 4, d483]
    h = c.sum(axis=1)  # expected-shape: h=[b483, d483]
    top, ix = jax.lax.top_k(y, 3)  # expected-shape: top=[b483, n483, 3]; ix=[b483, n483, 3]
    z = y @ w  # expected-shape: z=[b483, n483, d483]
    return y, h, z


def unpack_484(x: Float[Array, "b484 n484 48"], m: Float[Array, "16 32"]):
    q, k, v = jnp.split(x, 3, axis=-1)  # expected-shape: q=[b484, n484, 16]; k=[b484, n484, 16]; v=[b484, n484, 16]
    qk = jnp.einsum('bnd,bmd->bnm', q, k)  # expected-shape: qk=[b484, n484, n484]
    u, sv, vh = jnp.linalg.svd(m)  # expected-shape: u=[16, 16]; sv=[16]; vh=[32, 32]
    top, ti = jax.lax.top_k(v, 2)  # expected-shape: top=[b484, n484, 2]; ti=[b484, n484, 2]
    c1, c2 = jnp.split(m, 2, axis=1)  # expected-shape: c1=[16, 16]; c2=[16, 16]
    return qk, u, c1


