class Attn493(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_493 = nn.Linear(64, 192)
        self.proj_493 = nn.Linear(64, 64)
        self.norm_493 = nn.LayerNorm(64)

    def forward(self, x: Float[Array, "b493 s493 64"]):
        qkv = self.qkv_493(x)  # expected-shape: qkv=[b493, s493, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b493, s493, 64]; k=[b493, s493, 64]; v=[b493, s493, 64]
        q = q.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: q=[b493, s493, 8, 8]
        k = k.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: k=[b493, s493, 8, 8]
        v = v.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: v=[b493, s493, 8, 8]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b493, 8, s493, 8]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b493, 8, 8, s493]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b493, 8, s493, 8]
        scores = q @ k  # expected-shape: scores=[b493, 8, s493, s493]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b493, 8, s493, s493]
        ctx = attn @ v  # expected-shape: ctx=[b493, 8, s493, 8]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b493, s493, 8, 8]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b493, s493, 64]
        out = self.proj_493(ctx)  # expected-shape: out=[b493, s493, 64]
        out = self.norm_493(out + x)  # expected-shape: out=[b493, s493, 64]
        return out


